  "mounted.fiDetails.firstFill": "\u062A\u0631\u062A\u0628\u0637 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u0633\u062C\u0651\u0644\u0629 \u0628\u0627\u0644\u0641\u0639\u0644 \u0628\u0627\u0644\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0645\u064F\u0639\u062F\u0651\u0629 \u0648\u0644\u0627 \u064A\u0645\u0643\u0646 \u062A\u063A\u064A\u064A\u0631\u0647\u0627 \u0647\u0646\u0627. \u064A\u0645\u0643\u0646\u0643 \u062A\u0633\u062C\u064A\u0644 \u0623\u064A \u0628\u064A\u0627\u0646 \u0644\u0627 \u064A\u0632\u0627\u0644 \u0641\u0627\u0631\u063A\u064B\u0627\u060C \u0648\u064A\u064F\u0635\u062F\u0631 \u0625\u064A\u0635\u0627\u0644 \u0644\u0643\u0644 \u0625\u062F\u062E\u0627\u0644 \u0623\u0648\u0644.",
  "mounted.fiDetails.businessId": "\u0645\u0639\u0631\u0651\u0641 \u0627\u0644\u0634\u0631\u0643\u0629 \u0627\u0644\u0641\u0646\u0644\u0646\u062F\u064A (Y-tunnus)",
