  "mounted.ownerSetup.confirm": "\u0623\u0624\u0643\u062F \u0623\u0646 \u0647\u0630\u0647 \u0634\u0631\u0643\u0629 \u0641\u0646\u0644\u0646\u062F\u064A\u0629 \u0645\u062D\u062F\u0648\u062F\u0629 (Oy) \u0648\u0623\u0646 \u0647\u0630\u0647 \u0628\u064A\u0627\u0646\u0627\u062A\u0647\u0627 \u0627\u0644\u0641\u0639\u0644\u064A\u0629.",
  "mounted.ownerSetup.save": "\u062D\u0641\u0638 \u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0634\u0631\u0643\u0629",
