  "mounted.ownerSetup.pending": "\u062A\u062C\u0631\u0628\u062A\u0643 \u0628\u0627\u0646\u062A\u0638\u0627\u0631 \u0627\u0644\u062A\u0641\u0639\u064A\u0644",
  "mounted.ownerSetup.next": "\u062A\u0645 \u062D\u0641\u0638 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0643. \u0623\u062E\u0628\u0631 \u0645\u062D\u0627\u0633\u0628\u0643 \u0628\u0628\u0631\u064A\u062F \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0627\u0644\u0638\u0627\u0647\u0631 \u0623\u062F\u0646\u0627\u0647 \u0644\u064A\u0631\u0627\u062C\u0639 \u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0645\u062D\u0627\u0633\u0628\u0629 \u0627\u0644\u0634\u0631\u0643\u0629 \u0648\u064A\u0641\u0639\u0651\u0644 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0643. \u0644\u0645 \u062A\u064F\u0631\u0633\u0644 \u0631\u0633\u0627\u0644\u0629 \u062A\u0641\u0639\u064A\u0644 \u062A\u0644\u0642\u0627\u0626\u064A\u064B\u0627.",
  "mounted.ownerSetup.noPayment": "\u0644\u0627 \u062A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u0634\u0631\u0627\u0621 \u062E\u0637\u0629 \u0644\u0647\u0630\u0647 \u0627\u0644\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u062F\u0627\u062E\u0644\u064A\u0629. \u064A\u0628\u0642\u0649 \u0631\u0641\u0639 \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u063A\u064A\u0631 \u0645\u062A\u0627\u062D \u062D\u062A\u0649 \u062A\u0641\u0639\u064A\u0644 \u0634\u0631\u0643\u062A\u0643.",
  "mounted.ownerSetup.refresh": "\u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u062D\u0627\u0644\u0629 \u0627\u0644\u0625\u0639\u062F\u0627\u062F",
