  "mounted.pilot.noClients": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644 \u0641\u0646\u0644\u0646\u062F\u064A\u0629 \u0645\u062A\u0627\u062D\u0629. \u064A\u062C\u0628 \u0623\u0646 \u064A\u0633\u062C\u0644 \u0627\u0644\u0645\u0627\u0644\u0643 \u0623\u0648\u0644\u0627\u064B \u0648\u064A\u0646\u0634\u0626 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0647.",
  "mounted.pilot.operator": "\u0627\u0644\u0639\u0636\u0648 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0627\u0644\u0625\u0639\u062F\u0627\u062F:",
  "mounted.pilot.company": "\u0627\u0633\u0645 \u0627\u0644\u0634\u0631\u0643\u0629 \u0627\u0644\u0645\u0624\u0643\u062F",
  "mounted.pilot.scope": "\u0641\u0646\u0644\u0646\u062F\u0627 \xB7 Oy \xB7 EUR \xB7 \u062F\u0641\u062A\u0631 \u0623\u0633\u062A\u0627\u0630 Donna \xB7 \u062F\u0641\u0627\u062A\u0631 \u0625\u062F\u0627\u0631\u064A\u0629",
