  "mounted.pilot.alreadyPrepared": "\u062A\u0645 \u0625\u0639\u062F\u0627\u062F \u0627\u0644\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u062F\u0627\u062E\u0644\u064A\u0629 \u0645\u0633\u0628\u0642\u0627\u064B",
  "mounted.pilot.runtimeIncomplete": "\u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629: \u063A\u064A\u0631 \u0645\u0643\u062A\u0645\u0644\u0629. \u0644\u0627 \u062A\u0632\u0627\u0644 \u062C\u0627\u0647\u0632\u064A\u0629 \u0627\u0644\u0633\u062D\u0627\u0628\u0629 \u0648\u0635\u0644\u0627\u062D\u064A\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629 \u0648\u0627\u0644\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062A\u0636\u0627\u0641\u0629 \u062A\u062A\u0637\u0644\u0628 \u0627\u0644\u062A\u062D\u0642\u0642. \u0645\u0633\u0648\u062F\u0627\u062A \u0627\u0644\u0623\u0633\u0626\u0644\u0629 \u0644\u0627 \u062A\u0639\u0646\u064A \u0627\u0643\u062A\u0645\u0627\u0644 \u0645\u0633\u0643 \u0627\u0644\u062F\u0641\u0627\u062A\u0631.",
