  "operator.action.detail.existingFact": "\u062D\u0642\u064A\u0642\u0629 \u0645\u0648\u062C\u0648\u062F\u0629",
  "operator.action.detail.memoryApply": "\u062A\u064F\u0643\u062A\u0628 \u0641\u064A \u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0639\u0646\u062F \u0627\u0644\u062A\u0637\u0628\u064A\u0642\u061B \u0648\u064A\u0645\u0643\u0646 \u062A\u062C\u0627\u0647\u0644\u0647\u0627 \u0644\u0627\u062D\u0642\u064B\u0627 \u0639\u0628\u0631 \u0627\u0644\u062D\u0648\u0643\u0645\u0629",
  "operator.action.detail.currentFact": "\u0627\u0644\u062D\u0642\u064A\u0642\u0629 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 {index} \u2014 \u0627\u0633\u062A\u0628\u062F\u0644\u0647\u0627 \u0623\u0648 \u0623\u0628\u0642\u0647\u0627",
  "operator.action.detail.currentCodingOnApply": "\u064A\u064F\u062D\u062F\u0651\u064E\u062F \u0627\u0644\u062A\u0631\u0645\u064A\u0632 \u0627\u0644\u062D\u0627\u0644\u064A \u0639\u0646\u062F \u0627\u0644\u062A\u0637\u0628\u064A\u0642",
  "operator.action.detail.priorValueOnApply": "\u062A\u064F\u0642\u0631\u0623 \u0627\u0644\u0642\u064A\u0645\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0639\u0646\u062F \u0627\u0644\u062A\u0637\u0628\u064A\u0642",
