// src/i18n/catalogs/ar-AE/mounted.js
var EXACT = Object.freeze({
  "Your accounting firm gives you access": "\u0645\u0643\u062A\u0628 \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u0629 \u0627\u0644\u062E\u0627\u0635 \u0628\u0643 \u064A\u0645\u0646\u062D\u0643 \u0627\u0644\u0648\u0635\u0648\u0644",
  "This portal is provided by your accounting firm. Ask your firm to turn on your access to upload documents and answer questions.": "\u0647\u0630\u0647 \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u0645\u0642\u062F\u064E\u0651\u0645\u0629 \u0645\u0646 \u0645\u0643\u062A\u0628 \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u0629 \u0627\u0644\u062E\u0627\u0635 \u0628\u0643. \u0627\u0637\u0644\u0628 \u0645\u0646 \u0645\u0643\u062A\u0628\u0643 \u062A\u0641\u0639\u064A\u0644 \u0648\u0635\u0648\u0644\u0643 \u0644\u0631\u0641\u0639 \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0648\u0627\u0644\u0625\u062C\u0627\u0628\u0629 \u0639\u0646 \u0627\u0644\u0623\u0633\u0626\u0644\u0629.",
  "Your earlier plan has ended. Manage billing to see your invoices. From now on, your accounting firm gives you access to this portal.": "\u0627\u0646\u062A\u0647\u062A \u062E\u0637\u062A\u0643 \u0627\u0644\u0633\u0627\u0628\u0642\u0629. \u0627\u0641\u062A\u062D \u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0641\u0648\u062A\u0631\u0629 \u0644\u0639\u0631\u0636 \u0641\u0648\u0627\u062A\u064A\u0631\u0643. \u0645\u0646 \u0627\u0644\u0622\u0646 \u0641\u0635\u0627\u0639\u062F\u064B\u0627\u060C \u064A\u0645\u0646\u062D\u0643 \u0645\u0643\u062A\u0628 \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u0629 \u0627\u0644\u062E\u0627\u0635 \u0628\u0643 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0628\u0648\u0627\u0628\u0629.",
  "Document processing and review": "\u0645\u0639\u0627\u0644\u062C\u0629 \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0648\u0645\u0631\u0627\u062C\u0639\u062A\u0647\u0627",
  "Save and review documents and coding. Accounting posting is unavailable in this workspace.": "\u0627\u062D\u0641\u0638 \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0648\u0627\u0644\u062A\u0635\u0646\u064A\u0641\u0627\u062A \u0648\u0631\u0627\u062C\u0639\u0647\u0627. \u062A\u0631\u062D\u064A\u0644 \u0627\u0644\u0642\u064A\u0648\u062F \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u064A\u0629 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D \u0641\u064A \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0647\u0630\u0647.",
  "Bookkeeping start date": "\u062A\u0627\u0631\u064A\u062E \u0628\u062F\u0621 \u0645\u0633\u0643 \u0627\u0644\u062F\u0641\u0627\u062A\u0631",
  "I confirm this start date, SGD as the currency, management books, and the Donna ledger.": "\u0623\u0624\u0643\u062F \u062A\u0627\u0631\u064A\u062E \u0627\u0644\u0628\u062F\u0621 \u0647\u0630\u0627\u060C \u0648\u0627\u0644\u062F\u0648\u0644\u0627\u0631 \u0627\u0644\u0633\u0646\u063A\u0627\u0641\u0648\u0631\u064A \u0639\u0645\u0644\u0629\u064B\u060C \u0648\u0627\u0644\u062F\u0641\u0627\u062A\u0631 \u0627\u0644\u0625\u062F\u0627\u0631\u064A\u0629\u060C \u0648\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u062F\u0641\u062A\u0631 \u0623\u0633\u062A\u0627\u0630 Donna.",
  "GST registration stays unknown until supported registration evidence is recorded. A Bizfile alone does not confirm it.": "\u062A\u0638\u0644 \u062D\u0627\u0644\u0629 \u0627\u0644\u062A\u0633\u062C\u064A\u0644 \u0641\u064A \u0636\u0631\u064A\u0628\u0629 \u0627\u0644\u0633\u0644\u0639 \u0648\u0627\u0644\u062E\u062F\u0645\u0627\u062A \u063A\u064A\u0631 \u0645\u0639\u0631\u0648\u0641\u0629 \u0625\u0644\u0649 \u0623\u0646 \u064A\u064F\u0633\u062C\u064E\u0651\u0644 \u062F\u0644\u064A\u0644 \u0645\u0624\u064A\u062F \u0644\u0644\u062A\u0633\u062C\u064A\u0644. \u0645\u0644\u0641 Bizfile \u0648\u062D\u062F\u0647 \u0644\u0627 \u064A\u0624\u0643\u062F\u0647\u0627.",
  "Review sign-in recovery": "\u0645\u0631\u0627\u062C\u0639\u0629 \u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644",
  "Your previous sign-in was deleted. You can ask an operator to reconnect this empty workspace to your current confirmed sign-in.": "\u062A\u0645 \u062D\u0630\u0641 \u062A\u0633\u062C\u064A\u0644 \u062F\u062E\u0648\u0644\u0643 \u0627\u0644\u0633\u0627\u0628\u0642. \u064A\u0645\u0643\u0646\u0643 \u0623\u0646 \u062A\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u0634\u063A\u0651\u0644 \u0631\u0628\u0637 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0641\u0627\u0631\u063A\u0629 \u0647\u0630\u0647 \u0628\u062A\u0633\u062C\u064A\u0644 \u062F\u062E\u0648\u0644\u0643 \u0627\u0644\u062D\u0627\u0644\u064A \u0627\u0644\u0645\u0624\u0643\u0651\u062F.",
  "I own this company and request that this workspace be reconnected to my current sign-in. An operator must approve this request.": "\u0623\u0646\u0627 \u0645\u0627\u0644\u0643 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0643\u0629 \u0648\u0623\u0637\u0644\u0628 \u0625\u0639\u0627\u062F\u0629 \u0631\u0628\u0637 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0647\u0630\u0647 \u0628\u062A\u0633\u062C\u064A\u0644 \u062F\u062E\u0648\u0644\u064A \u0627\u0644\u062D\u0627\u0644\u064A. \u064A\u062C\u0628 \u0623\u0646 \u064A\u0648\u0627\u0641\u0642 \u0627\u0644\u0645\u0634\u063A\u0651\u0644 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0637\u0644\u0628.",
  "Request sign-in recovery": "\u0637\u0644\u0628 \u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644",
  "Waiting for operator approval": "\u0628\u0627\u0646\u062A\u0638\u0627\u0631 \u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u0645\u0634\u063A\u0651\u0644",
  "Your request is recorded. After the operator approves it, review this workspace again to confirm ownership. Processing remains unavailable until the separate readiness checks pass.": "\u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u0637\u0644\u0628\u0643. \u0628\u0639\u062F \u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u0645\u0634\u063A\u0651\u0644\u060C \u0631\u0627\u062C\u0639 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0645\u062C\u062F\u062F\u064B\u0627 \u0644\u062A\u0623\u0643\u064A\u062F \u0627\u0644\u0645\u0644\u0643\u064A\u0629. \u062A\u0638\u0644 \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629 \u062D\u062A\u0649 \u0627\u062C\u062A\u064A\u0627\u0632 \u0641\u062D\u0648\u0635 \u0627\u0644\u062C\u0627\u0647\u0632\u064A\u0629 \u0627\u0644\u0645\u0646\u0641\u0635\u0644\u0629.",
  "Withdraw recovery request": "\u0633\u062D\u0628 \u0637\u0644\u0628 \u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629",
  "Recovery request withdrawn": "\u062A\u0645 \u0633\u062D\u0628 \u0637\u0644\u0628 \u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629",
  "No sign-in binding was changed. You can review recovery again if needed.": "\u0644\u0645 \u064A\u062A\u063A\u064A\u0631 \u0631\u0628\u0637 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644. \u064A\u0645\u0643\u0646\u0643 \u0645\u0631\u0627\u062C\u0639\u0629 \u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u0645\u062C\u062F\u062F\u064B\u0627 \u0639\u0646\u062F \u0627\u0644\u062D\u0627\u062C\u0629.",
  "The recovery response could not be verified. Review again before continuing.": "\u062A\u0639\u0630\u0651\u0631 \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0633\u062A\u062C\u0627\u0628\u0629 \u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629. \u0631\u0627\u062C\u0639 \u0645\u062C\u062F\u062F\u064B\u0627 \u0642\u0628\u0644 \u0627\u0644\u0645\u062A\u0627\u0628\u0639\u0629.",
  "This owner requested recovery after their previous sign-in was deleted. Approval reconnects only this existing empty workspace to their current confirmed sign-in.": "\u0637\u0644\u0628 \u0647\u0630\u0627 \u0627\u0644\u0645\u0627\u0644\u0643 \u0627\u0644\u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u0628\u0639\u062F \u062D\u0630\u0641 \u062A\u0633\u062C\u064A\u0644 \u062F\u062E\u0648\u0644\u0647 \u0627\u0644\u0633\u0627\u0628\u0642. \u062A\u0639\u064A\u062F \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0631\u0628\u0637 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0627\u0644\u0641\u0627\u0631\u063A\u0629 \u0647\u0630\u0647 \u0641\u0642\u0637 \u0628\u062A\u0633\u062C\u064A\u0644 \u062F\u062E\u0648\u0644\u0647 \u0627\u0644\u062D\u0627\u0644\u064A \u0627\u0644\u0645\u0624\u0643\u0651\u062F.",
  "I have reviewed this owner\u2019s request and approve reconnecting their existing empty workspace.": "\u0631\u0627\u062C\u0639\u062A \u0637\u0644\u0628 \u0647\u0630\u0627 \u0627\u0644\u0645\u0627\u0644\u0643 \u0648\u0623\u0648\u0627\u0641\u0642 \u0639\u0644\u0649 \u0625\u0639\u0627\u062F\u0629 \u0631\u0628\u0637 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0647 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0627\u0644\u0641\u0627\u0631\u063A\u0629.",
  "Approve sign-in recovery": "\u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0639\u0644\u0649 \u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644",
  "Sign-in recovery recorded": "\u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u0627\u0633\u062A\u0639\u0627\u062F\u0629 \u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062F\u062E\u0648\u0644",
  "The owner must now return to their workspace confirmation page and review again. Pilot preparation and processing readiness remain separate steps.": "\u064A\u062C\u0628 \u0639\u0644\u0649 \u0627\u0644\u0645\u0627\u0644\u0643 \u0627\u0644\u0622\u0646 \u0627\u0644\u0639\u0648\u062F\u0629 \u0625\u0644\u0649 \u0635\u0641\u062D\u0629 \u062A\u0623\u0643\u064A\u062F \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0647 \u0648\u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0645\u062C\u062F\u062F\u064B\u0627. \u064A\u0638\u0644 \u0625\u0639\u062F\u0627\u062F \u0627\u0644\u062A\u062C\u0631\u0628\u0629 \u0648\u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u062C\u0627\u0647\u0632\u064A\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629 \u062E\u0637\u0648\u062A\u064A\u0646 \u0645\u0646\u0641\u0635\u0644\u062A\u064A\u0646.",
  "Confirm your existing workspace": "\u062A\u0623\u0643\u064A\u062F \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0643 \u0627\u0644\u062D\u0627\u0644\u064A\u0629",
  "Review the company and signed-in owner before confirming this empty Finnish workspace for pilot setup.": "\u0631\u0627\u062C\u0639 \u0627\u0644\u0634\u0631\u0643\u0629 \u0648\u0627\u0644\u0645\u0627\u0644\u0643 \u0627\u0644\u0645\u0633\u062C\u0651\u0644 \u062F\u062E\u0648\u0644\u0647 \u0642\u0628\u0644 \u062A\u0623\u0643\u064A\u062F \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0641\u0646\u0644\u0646\u062F\u064A\u0629 \u0627\u0644\u0641\u0627\u0631\u063A\u0629 \u0647\u0630\u0647 \u0644\u0625\u0639\u062F\u0627\u062F \u0627\u0644\u062A\u062C\u0631\u0628\u0629.",
  "Sign in to review your workspace": "\u0633\u062C\u0651\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0643",
  "Checking your workspace\u2026": "\u062C\u0627\u0631\u064D \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644\u0643\u2026",
  "Finnish Oy \xB7 Existing empty workspace": "\u0634\u0631\u0643\u0629 \u0641\u0646\u0644\u0646\u062F\u064A\u0629 \u0645\u062D\u062F\u0648\u062F\u0629 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064A\u0629 \xB7 \u0645\u0633\u0627\u062D\u0629 \u0639\u0645\u0644 \u062D\u0627\u0644\u064A\u0629 \u0641\u0627\u0631\u063A\u0629",
  "I confirm that I am the owner of this company and want this existing workspace reviewed for the hosted pilot.": "\u0623\u0624\u0643\u062F \u0623\u0646\u0646\u064A \u0645\u0627\u0644\u0643 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0643\u0629 \u0648\u0623\u0631\u063A\u0628 \u0641\u064A \u0645\u0631\u0627\u062C\u0639\u0629 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0647\u0630\u0647 \u0644\u0644\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062A\u0636\u0627\u0641\u0629.",
  "Confirm workspace ownership": "\u062A\u0623\u0643\u064A\u062F \u0645\u0644\u0643\u064A\u0629 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644",
  "Owner confirmation recorded": "\u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u062A\u0623\u0643\u064A\u062F \u0627\u0644\u0645\u0627\u0644\u0643",
  "The operator can now review your confirmation and prepare the pilot. Document processing still needs its separate readiness checks.": "\u064A\u0645\u0643\u0646 \u0644\u0644\u0645\u0634\u063A\u0651\u0644 \u0627\u0644\u0622\u0646 \u0645\u0631\u0627\u062C\u0639\u0629 \u062A\u0623\u0643\u064A\u062F\u0643 \u0648\u0625\u0639\u062F\u0627\u062F \u0627\u0644\u062A\u062C\u0631\u0628\u0629. \u0644\u0627 \u062A\u0632\u0627\u0644 \u0645\u0639\u0627\u0644\u062C\u0629 \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0628\u062D\u0627\u062C\u0629 \u0625\u0644\u0649 \u0641\u062D\u0648\u0635 \u0627\u0644\u062C\u0627\u0647\u0632\u064A\u0629 \u0627\u0644\u0645\u0646\u0641\u0635\u0644\u0629 \u0627\u0644\u062E\u0627\u0635\u0629 \u0628\u0647\u0627.",
  "Available for operator review until:": "\u0645\u062A\u0627\u062D \u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0627\u0644\u0645\u0634\u063A\u0651\u0644 \u062D\u062A\u0649:",
  "Review workspace again": "\u0645\u0631\u0627\u062C\u0639\u0629 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0645\u062C\u062F\u062F\u064B\u0627",
  "Current owner confirmation:": "\u062A\u0623\u0643\u064A\u062F \u0627\u0644\u0645\u0627\u0644\u0643 \u0627\u0644\u062D\u0627\u0644\u064A:",
  "Hosted pilot readiness": "\u062C\u0627\u0647\u0632\u064A\u0629 \u0627\u0644\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062A\u0636\u0627\u0641\u0629",
  "Review runtime checks before enabling this pilot\u2019s document processing.": "\u0631\u0627\u062C\u0639 \u0641\u062D\u0648\u0635 \u0628\u064A\u0626\u0629 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0642\u0628\u0644 \u062A\u0641\u0639\u064A\u0644 \u0645\u0639\u0627\u0644\u062C\u0629 \u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0647\u0630\u0647 \u0627\u0644\u062A\u062C\u0631\u0628\u0629.",
  "Refresh readiness review": "\u062A\u062D\u062F\u064A\u062B \u0645\u0631\u0627\u062C\u0639\u0629 \u0627\u0644\u062C\u0627\u0647\u0632\u064A\u0629",
  "Host checks passed": "\u0646\u062C\u062D\u062A \u0641\u062D\u0648\u0635 \u0628\u064A\u0626\u0629 \u0627\u0644\u062A\u0634\u063A\u064A\u0644",
  "Host checks incomplete": "\u0641\u062D\u0648\u0635 \u0628\u064A\u0626\u0629 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u063A\u064A\u0631 \u0645\u0643\u062A\u0645\u0644\u0629",
  "Entity admission ready": "\u0627\u0644\u0643\u064A\u0627\u0646 \u062C\u0627\u0647\u0632 \u0644\u0644\u0645\u0639\u0627\u0644\u062C\u0629",
  "Entity admission incomplete": "\u062C\u0627\u0647\u0632\u064A\u0629 \u0627\u0644\u0643\u064A\u0627\u0646 \u063A\u064A\u0631 \u0645\u0643\u062A\u0645\u0644\u0629",
  "Deployment verification expires:": "\u062A\u0646\u062A\u0647\u064A \u0635\u0644\u0627\u062D\u064A\u0629 \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0644\u0646\u0634\u0631:",
  "Run one small synthetic request per unverified provider and request the existing worker checks. This tests transport, not bookkeeping results.": "\u0634\u063A\u0651\u0644 \u0637\u0644\u0628\u064B\u0627 \u0627\u0635\u0637\u0646\u0627\u0639\u064A\u064B\u0627 \u0635\u063A\u064A\u0631\u064B\u0627 \u0644\u0643\u0644 \u0645\u0632\u0648\u0651\u062F \u0644\u0645 \u064A\u062A\u0645 \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646\u0647 \u0648\u0627\u0637\u0644\u0628 \u0641\u062D\u0648\u0635 \u0627\u0644\u0639\u0627\u0645\u0644\u064A\u0646 \u0627\u0644\u062D\u0627\u0644\u064A\u064A\u0646. \u0647\u0630\u0627 \u064A\u0641\u062D\u0635 \u0627\u0644\u0627\u062A\u0635\u0627\u0644\u060C \u0648\u0644\u064A\u0633 \u0627\u0644\u0646\u062A\u0627\u0626\u062C \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u064A\u0629.",
  "Run dependency checks": "\u062A\u0634\u063A\u064A\u0644 \u0641\u062D\u0648\u0635 \u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F\u064A\u0627\u062A",
  "Dependency checks requested. Refresh this review to see persisted results.": "\u062A\u0645 \u0637\u0644\u0628 \u0641\u062D\u0648\u0635 \u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F\u064A\u0627\u062A. \u062D\u062F\u0651\u062B \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0644\u0644\u0627\u0637\u0644\u0627\u0639 \u0639\u0644\u0649 \u0627\u0644\u0646\u062A\u0627\u0626\u062C \u0627\u0644\u0645\u062D\u0641\u0648\u0638\u0629.",
  "Review exact configuration changes": "\u0645\u0631\u0627\u062C\u0639\u0629 \u062A\u063A\u064A\u064A\u0631\u0627\u062A \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0645\u062D\u062F\u062F\u0629",
  "These manual canary settings apply only to the selected client.": "\u062A\u0646\u0637\u0628\u0642 \u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u064A\u062F\u0648\u064A\u0629 \u0647\u0630\u0647 \u0639\u0644\u0649 \u0627\u0644\u0639\u0645\u064A\u0644 \u0627\u0644\u0645\u062D\u062F\u062F \u0641\u0642\u0637.",
  "Current server configuration (read only)": "\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u062E\u0627\u062F\u0645 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 (\u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u0642\u0637)",
  "Existing materiality limits still apply. Held items need an explicit operator action. No external messages, filing or material authority are granted here.": "\u062A\u0638\u0644 \u062D\u062F\u0648\u062F \u0627\u0644\u0623\u0647\u0645\u064A\u0629 \u0627\u0644\u0646\u0633\u0628\u064A\u0629 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0633\u0627\u0631\u064A\u0629. \u062A\u062D\u062A\u0627\u062C \u0627\u0644\u0628\u0646\u0648\u062F \u0627\u0644\u0645\u0639\u0644\u0651\u0642\u0629 \u0625\u0644\u0649 \u0625\u062C\u0631\u0627\u0621 \u0635\u0631\u064A\u062D \u0645\u0646 \u0627\u0644\u0645\u0634\u063A\u0651\u0644. \u0644\u0627 \u064A\u064F\u0645\u0646\u062D \u0647\u0646\u0627 \u0625\u0630\u0646 \u0628\u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u062E\u0627\u0631\u062C\u064A\u0629 \u0623\u0648 \u0627\u0644\u0625\u064A\u062F\u0627\u0639 \u0623\u0648 \u0635\u0644\u0627\u062D\u064A\u0629 \u0627\u0644\u0645\u0628\u0627\u0644\u063A \u0627\u0644\u062C\u0648\u0647\u0631\u064A\u0629.",
  "I reviewed this client and the exact configuration changes.": "\u0631\u0627\u062C\u0639\u062A \u0647\u0630\u0627 \u0627\u0644\u0639\u0645\u064A\u0644 \u0648\u062A\u063A\u064A\u064A\u0631\u0627\u062A \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0645\u062D\u062F\u062F\u0629.",
  "Apply reviewed processing settings": "\u062A\u0637\u0628\u064A\u0642 \u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629 \u0627\u0644\u062A\u064A \u062A\u0645\u062A \u0645\u0631\u0627\u062C\u0639\u062A\u0647\u0627",
  "Configuration saved. Entity readiness:": "\u062A\u0645 \u062D\u0641\u0638 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A. \u062C\u0627\u0647\u0632\u064A\u0629 \u0627\u0644\u0643\u064A\u0627\u0646:",
  "Deployed source": "\u0627\u0644\u0645\u0635\u062F\u0631 \u0627\u0644\u0645\u0646\u0634\u0648\u0631",
  "Database schema": "\u0628\u0646\u064A\u0629 \u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A",
  "Durable workers": "\u0627\u0644\u0639\u0627\u0645\u0644\u0648\u0646 \u0630\u0648\u0648 \u0627\u0644\u062A\u0646\u0641\u064A\u0630 \u0627\u0644\u0645\u0633\u062A\u0645\u0631",
  "Private file storage": "\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0627\u0644\u062E\u0627\u0635",
  "Model routes": "\u0645\u0633\u0627\u0631\u0627\u062A \u0627\u0644\u0646\u0645\u0627\u0630\u062C",
  "Provider responses": "\u0627\u0633\u062A\u062C\u0627\u0628\u0627\u062A \u0627\u0644\u0645\u0632\u0648\u0651\u062F\u064A\u0646",
  "Policy artifacts": "\u0645\u0644\u0641\u0627\u062A \u0627\u0644\u0633\u064A\u0627\u0633\u0629",
  "Configuration controls": "\u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A",
  "Accounting integration": "\u0627\u0644\u062A\u0643\u0627\u0645\u0644 \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u064A",
  "Usage measurement": "\u0642\u064A\u0627\u0633 \u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645",
  "Failure details": "\u062A\u0641\u0627\u0635\u064A\u0644 \u0627\u0644\u0639\u0637\u0644",
  "Last retry:": "\u0622\u062E\u0631 \u0645\u062D\u0627\u0648\u0644\u0629:",
  "Next repairs": "\u0627\u0644\u0625\u0635\u0644\u0627\u062D\u0627\u062A \u0627\u0644\u062A\u0627\u0644\u064A\u0629",
  "What was repaired?": "\u0645\u0627 \u0627\u0644\u0630\u064A \u062A\u0645 \u0625\u0635\u0644\u0627\u062D\u0647\u061F",
  "Runtime repairs": "\u0625\u0635\u0644\u0627\u062D\u0627\u062A \u0627\u0644\u062A\u0634\u063A\u064A\u0644",
  "Workspace members can take responsibility for a runtime failure and retry processing after its cause is repaired. A retry stays open until processing succeeds.": "\u064A\u0645\u0643\u0646 \u0644\u0623\u0639\u0636\u0627\u0621 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u062A\u0648\u0644\u0651\u064A \u0645\u0633\u0624\u0648\u0644\u064A\u0629 \u0639\u0637\u0644 \u0641\u064A \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0648\u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0645\u062D\u0627\u0648\u0644\u0629 \u0628\u0639\u062F \u0625\u0635\u0644\u0627\u062D \u0633\u0628\u0628\u0647. \u062A\u0628\u0642\u0649 \u0627\u0644\u0645\u062D\u0627\u0648\u0644\u0629 \u0645\u0641\u062A\u0648\u062D\u0629 \u062D\u062A\u0649 \u062A\u0646\u062C\u062D \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629.",
  "Loading runtime repairs\u2026": "\u062C\u0627\u0631\u064D \u062A\u062D\u0645\u064A\u0644 \u0625\u0635\u0644\u0627\u062D\u0627\u062A \u0627\u0644\u062A\u0634\u063A\u064A\u0644\u2026",
  "No runtime failures need attention.": "\u0644\u0627 \u062A\u0648\u062C\u062F \u0623\u0639\u0637\u0627\u0644 \u0641\u064A \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u062A\u062A\u0637\u0644\u0628 \u0627\u0644\u0645\u062A\u0627\u0628\u0639\u0629.",
  "Runtime repairs could not be updated. Member access is required. Refresh or retry.": "\u062A\u0639\u0630\u0651\u0631 \u062A\u062D\u062F\u064A\u062B \u0625\u0635\u0644\u0627\u062D\u0627\u062A \u0627\u0644\u062A\u0634\u063A\u064A\u0644. \u064A\u0644\u0632\u0645 \u0627\u0644\u0648\u0635\u0648\u0644 \u0628\u0635\u0644\u0627\u062D\u064A\u0629 \u0639\u0636\u0648. \u062D\u062F\u0651\u062B \u0627\u0644\u0635\u0641\u062D\u0629 \u0623\u0648 \u0623\u0639\u062F \u0627\u0644\u0645\u062D\u0627\u0648\u0644\u0629.",
  "A saved owner reply needs a runtime repair before processing can finish.": "\u064A\u062A\u0637\u0644\u0628 \u0631\u062F\u0651 \u0627\u0644\u0645\u0627\u0644\u0643 \u0627\u0644\u0645\u062D\u0641\u0648\u0638 \u0625\u0635\u0644\u0627\u062D\u064B\u0627 \u0641\u064A \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0642\u0628\u0644 \u0625\u062A\u0645\u0627\u0645 \u0645\u0639\u0627\u0644\u062C\u062A\u0647.",
  "Transaction coding needs a runtime repair.": "\u064A\u062A\u0637\u0644\u0628 \u062A\u0635\u0646\u064A\u0641 \u0627\u0644\u0645\u0639\u0627\u0645\u0644\u0629 \u0625\u0635\u0644\u0627\u062D\u064B\u0627 \u0641\u064A \u0627\u0644\u062A\u0634\u063A\u064A\u0644.",
  "Posting needs a runtime repair. Existing posting permissions still apply.": "\u064A\u062A\u0637\u0644\u0628 \u0627\u0644\u062A\u0631\u062D\u064A\u0644 \u0625\u0635\u0644\u0627\u062D\u064B\u0627 \u0641\u064A \u0627\u0644\u062A\u0634\u063A\u064A\u0644. \u062A\u0638\u0644 \u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0627\u0644\u062A\u0631\u062D\u064A\u0644 \u0627\u0644\u062D\u0627\u0644\u064A\u0629 \u0633\u0627\u0631\u064A\u0629.",
  "Accounting posting is unavailable for this workspace.": "\u0627\u0644\u062A\u0631\u062D\u064A\u0644 \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u064A \u063A\u064A\u0631 \u0645\u062A\u0627\u062D \u0644\u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0647\u0630\u0647.",
  "Accounting support requires separate qualification and release. Configuration changes or recoding cannot enable posting in this review workspace.": "\u064A\u062A\u0637\u0644\u0628 \u062F\u0639\u0645 \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u0629 \u062A\u0623\u0647\u064A\u0644\u064B\u0627 \u0648\u0625\u0635\u062F\u0627\u0631\u064B\u0627 \u0645\u0646\u0641\u0635\u0644\u064A\u0646. \u0644\u0627 \u064A\u0645\u0643\u0646 \u0644\u062A\u063A\u064A\u064A\u0631\u0627\u062A \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A \u0623\u0648 \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u0635\u0646\u064A\u0641 \u062A\u0641\u0639\u064A\u0644 \u0627\u0644\u062A\u0631\u062D\u064A\u0644 \u0641\u064A \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u062E\u0635\u0635\u0629 \u0644\u0644\u0645\u0631\u0627\u062C\u0639\u0629 \u0647\u0630\u0647.",
  "Awaiting a workspace maintainer.": "\u0628\u0627\u0646\u062A\u0638\u0627\u0631 \u0645\u0633\u0624\u0648\u0644 \u0635\u064A\u0627\u0646\u0629 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644.",
  "Responsible member:": "\u0627\u0644\u0639\u0636\u0648 \u0627\u0644\u0645\u0633\u0624\u0648\u0644:",
  "Take responsibility": "\u062A\u0648\u0644\u0651\u064A \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064A\u0629",
  "Retry processing": "\u0625\u0639\u0627\u062F\u0629 \u0645\u062D\u0627\u0648\u0644\u0629 \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629",
  "Processing\u2026": "\u062C\u0627\u0631\u064D \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629\u2026",
  "Refresh repairs": "\u062A\u062D\u062F\u064A\u062B \u0627\u0644\u0625\u0635\u0644\u0627\u062D\u0627\u062A",
  "Your responsibility for this failure is recorded.": "\u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u0645\u0633\u0624\u0648\u0644\u064A\u062A\u0643 \u0639\u0646 \u0647\u0630\u0627 \u0627\u0644\u0639\u0637\u0644.",
  "Processing succeeded and the failure is closed.": "\u0646\u062C\u062D\u062A \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629 \u0648\u0623\u064F\u063A\u0644\u0642 \u0627\u0644\u0639\u0637\u0644.",
  "The repair attempt is recorded. This failure remains open until processing succeeds.": "\u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u0645\u062D\u0627\u0648\u0644\u0629 \u0627\u0644\u0625\u0635\u0644\u0627\u062D. \u064A\u0628\u0642\u0649 \u0647\u0630\u0627 \u0627\u0644\u0639\u0637\u0644 \u0645\u0641\u062A\u0648\u062D\u064B\u0627 \u062D\u062A\u0649 \u062A\u0646\u062C\u062D \u0627\u0644\u0645\u0639\u0627\u0644\u062C\u0629.",
  "Mounted product surface review": "\u0645\u0631\u0627\u062C\u0639\u0629 \u0623\u0633\u0637\u062D \u0627\u0644\u0645\u0646\u062A\u062C \u0627\u0644\u0645\u062B\u0628\u062A\u0629",
  "Development fixture \xB7 production components and realistic bidirectional content": "\u0628\u064A\u0626\u0629 \u062A\u0637\u0648\u064A\u0631 \xB7 \u0645\u0643\u0648\u0651\u0646\u0627\u062A \u0627\u0644\u0625\u0646\u062A\u0627\u062C \u0648\u0645\u062D\u062A\u0648\u0649 \u0648\u0627\u0642\u0639\u064A \u062B\u0646\u0627\u0626\u064A \u0627\u0644\u0627\u062A\u062C\u0627\u0647",
  "Venture creation": "\u0625\u0646\u0634\u0627\u0621 \u0645\u0646\u0634\u0623\u0629",
  "Accounting import": "\u0627\u0633\u062A\u064A\u0631\u0627\u062F \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0627\u0644\u0645\u062D\u0627\u0633\u0628\u064A\u0629",
  "Workspace shell": "\u0625\u0637\u0627\u0631 \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644",
  "Show the sidebar": "\u0625\u0638\u0647\u0627\u0631 \u0627\u0644\u0634\u0631\u064A\u0637 \u0627\u0644\u062C\u0627\u0646\u0628\u064A",
  "Hide the sidebar": "\u0625\u062E\u0641\u0627\u0621 \u0627\u0644\u0634\u0631\u064A\u0637 \u0627\u0644\u062C\u0627\u0646\u0628\u064A",
  "Firm entities": "\u0645\u0646\u0634\u0622\u062A \u0627\u0644\u0645\u0643\u062A\u0628",
  "Add venture": "\u0625\u0636\u0627\u0641\u0629 \u0645\u0646\u0634\u0623\u0629",
  "Venture scope": "\u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0646\u0634\u0623\u0629",
  "User menu": "\u0642\u0627\u0626\u0645\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645",
  "Keyboard shortcuts": "\u0627\u062E\u062A\u0635\u0627\u0631\u0627\u062A \u0644\u0648\u062D\u0629 \u0627\u0644\u0645\u0641\u0627\u062A\u064A\u062D",
  "Send feedback": "\u0625\u0631\u0633\u0627\u0644 \u0645\u0644\u0627\u062D\u0638\u0627\u062A",
  "Log out": "\u062A\u0633\u062C\u064A\u0644 \u0627\u0644\u062E\u0631\u0648\u062C",
  "This venture": "\u0647\u0630\u0647 \u0627\u0644\u0645\u0646\u0634\u0623\u0629",
  "All ventures": "\u0643\u0644 \u0627\u0644\u0645\u0646\u0634\u0622\u062A",
  "Collapse the dock": "\u0637\u064A \u0644\u0648\u062D\u0629 \u062F\u0648\u0646\u0627",
  "Open the Donna dock \u2014 chat and uploads": "\u0641\u062A\u062D \u0644\u0648\u062D\u0629 \u062F\u0648\u0646\u0627 \u2014 \u0627\u0644\u0645\u062D\u0627\u062F\u062B\u0629 \u0648\u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0627\u0644\u0645\u0631\u0641\u0648\u0639\u0629",
  "Settings sections": "\u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u0625\u0639\u062F\u0627\u062F\u0627\u062A",
  "AI & models": "\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0648\u0627\u0644\u0646\u0645\u0627\u0630\u062C",
  "Data & backup": "\u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A",
  "Your operator identity on this workspace.": "\u0647\u0648\u064A\u0629 \u0627\u0644\u0645\u0634\u063A\u0651\u0644 \u0627\u0644\u062E\u0627\u0635\u0629 \u0628\u0643 \u0641\u064A \u0645\u0633\u0627\u062D\u0629 \u0627\u0644\u0639\u0645\u0644 \u0647\u0630\u0647.",
  "Choose which events should interrupt you.": "\u0627\u062E\u062A\u0631 \u0627\u0644\u0623\u062D\u062F\u0627\u062B \u0627\u0644\u062A\u064A \u064A\u0646\u0628\u063A\u064A \u0623\u0646 \u062A\u0646\u0628\u0651\u0647\u0643.",
  "Move through Donna without leaving the keyboard.": "\u062A\u0646\u0642\u0651\u0644 \u0641\u064A \u062F\u0648\u0646\u0627 \u0645\u0646 \u062F\u0648\u0646 \u0645\u063A\u0627\u062F\u0631\u0629 \u0644\u0648\u062D\u0629 \u0627\u0644\u0645\u0641\u0627\u062A\u064A\u062D.",
  "The firm this appliance runs.": "\u0627\u0644\u0645\u0643\u062A\u0628 \u0627\u0644\u0630\u064A \u064A\u0639\u0645\u0644 \u0639\u0644\u064A\u0647 \u0647\u0630\u0627 \u0627\u0644\u062C\u0647\u0627\u0632.",
  "Set the boundary between Donna\u2019s work and your approval.": "\u062D\u062F\u0651\u062F \u0627\u0644\u0641\u0627\u0635\u0644 \u0628\u064A\u0646 \u0639\u0645\u0644 \u062F\u0648\u0646\u0627 \u0648\u0645\u0648\u0627\u0641\u0642\u062A\u0643.",
  "Choose which ventures the chat apps you connect can reach.": "\u0627\u062E\u062A\u0631 \u0627\u0644\u0645\u0646\u0634\u0622\u062A \u0627\u0644\u062A\u064A \u064A\u0645\u0643\u0646 \u0644\u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0627\u0644\u062F\u0631\u062F\u0634\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u0628\u0637\u0647\u0627 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064A\u0647\u0627.",
  "Review durable facts Donna uses in future work.": "\u0631\u0627\u062C\u0639 \u0627\u0644\u062D\u0642\u0627\u0626\u0642 \u0627\u0644\u062F\u0627\u0626\u0645\u0629 \u0627\u0644\u062A\u064A \u062A\u0633\u062A\u062E\u062F\u0645\u0647\u0627 \u062F\u0648\u0646\u0627 \u0641\u064A \u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0645\u0633\u062A\u0642\u0628\u0644\u064A\u0629.",
  "Plan, usage and included capacity.": "\u0627\u0644\u062E\u0637\u0629 \u0648\u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0648\u0627\u0644\u0633\u0639\u0629 \u0627\u0644\u0645\u0634\u0645\u0648\u0644\u0629.",
  "Inference routing and model receipts.": "\u062A\u0648\u062C\u064A\u0647 \u0627\u0644\u0627\u0633\u062A\u062F\u0644\u0627\u0644 \u0648\u0625\u064A\u0635\u0627\u0644\u0627\u062A \u0627\u0644\u0646\u0645\u0627\u0630\u062C.",
  "Book location, export and backup controls.": "\u0645\u0648\u0642\u0639 \u0627\u0644\u062F\u0641\u0627\u062A\u0631 \u0648\u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u062A\u0635\u062F\u064A\u0631 \u0648\u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A.",
  "Build and runtime information.": "\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0627\u0644\u0625\u0635\u062F\u0627\u0631 \u0648\u0628\u064A\u0626\u0629 \u0627\u0644\u062A\u0634\u063A\u064A\u0644.",
  "Account details are not available yet. Reload to try again.": "\u062A\u0641\u0627\u0635\u064A\u0644 \u0627\u0644\u062D\u0633\u0627\u0628 \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629 \u0628\u0639\u062F. \u0623\u0639\u062F \u062A\u062D\u0645\u064A\u0644 \u0627\u0644\u0635\u0641\u062D\u0629 \u0644\u0644\u0645\u062D\u0627\u0648\u0644\u0629 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649.",
  "This appliance signs itself in; there is no account to manage on this device.": "\u064A\u0633\u062C\u0651\u0644 \u0647\u0630\u0627 \u0627\u0644\u062C\u0647\u0627\u0632 \u062F\u062E\u0648\u0644\u0647 \u062A\u0644\u0642\u0627\u0626\u064A\u0627\u064B\u061B \u0644\u0627 \u064A\u0648\u062C\u062F \u062D\u0633\u0627\u0628 \u0644\u0625\u062F\u0627\u0631\u062A\u0647 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062C\u0647\u0627\u0632.",
  "Dragging files anywhere onto the window uploads them to the selected venture.": "\u064A\u0624\u062F\u064A \u0633\u062D\u0628 \u0627\u0644\u0645\u0644\u0641\u0627\u062A \u0625\u0644\u0649 \u0623\u064A \u0645\u0648\u0636\u0639 \u0641\u064A \u0627\u0644\u0646\u0627\u0641\u0630\u0629 \u0625\u0644\u0649 \u0631\u0641\u0639\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0627\u0644\u0645\u062D\u062F\u062F\u0629.",
  "Visible to the chat apps you connect. Every call lands in the audit trail.": "\u0645\u0631\u0626\u064A \u0644\u062A\u0637\u0628\u064A\u0642\u0627\u062A \u0627\u0644\u062F\u0631\u062F\u0634\u0629 \u0627\u0644\u062A\u064A \u062A\u0631\u0628\u0637\u0647\u0627. \u062A\u064F\u0633\u062C\u0651\u0644 \u0643\u0644 \u0627\u0633\u062A\u062F\u0639\u0627\u0621 \u0641\u064A \u0645\u0633\u0627\u0631 \u0627\u0644\u062A\u062F\u0642\u064A\u0642.",
  "Not visible. Never exposed.": "\u063A\u064A\u0631 \u0645\u0631\u0626\u064A. \u0644\u0645 \u062A\u062A\u0645 \u0625\u062A\u0627\u062D\u062A\u0647 \u0645\u0646 \u0642\u0628\u0644.",
  "What a connected chat app can do": "\u0645\u0627 \u064A\u0645\u0643\u0646 \u0644\u062A\u0637\u0628\u064A\u0642 \u062F\u0631\u062F\u0634\u0629 \u0645\u0631\u062A\u0628\u0637 \u0641\u0639\u0644\u0647",
  "One consent covers every chat surface: {surfaces}. A connected app can read the close status, open items, outstanding documents and audit trail of the ventures you turn on, ask Donna about them, and confirm an answer she proposed, through the same tracked path as the Confirm button in the portal. It cannot post, approve, file or send anything else, and Donna still enforces permissions and write controls.": "\u0645\u0648\u0627\u0641\u0642\u0629 \u0648\u0627\u062D\u062F\u0629 \u062A\u063A\u0637\u064A \u0643\u0644 \u0623\u0633\u0637\u062D \u0627\u0644\u062F\u0631\u062F\u0634\u0629: {surfaces}. \u064A\u0645\u0643\u0646 \u0644\u0644\u062A\u0637\u0628\u064A\u0642 \u0627\u0644\u0645\u0631\u062A\u0628\u0637 \u0642\u0631\u0627\u0621\u0629 \u062D\u0627\u0644\u0629 \u0627\u0644\u0625\u0642\u0641\u0627\u0644 \u0648\u0627\u0644\u0628\u0646\u0648\u062F \u0627\u0644\u0645\u0641\u062A\u0648\u062D\u0629 \u0648\u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u062D\u0642\u0629 \u0648\u0645\u0633\u0627\u0631 \u062A\u062F\u0642\u064A\u0642 \u0627\u0644\u0645\u0646\u0634\u0622\u062A \u0627\u0644\u062A\u064A \u062A\u0641\u0639\u0651\u0644\u0647\u0627\u060C \u0648\u0633\u0624\u0627\u0644 \u062F\u0648\u0646\u0627 \u0639\u0646\u0647\u0627\u060C \u0648\u062A\u0623\u0643\u064A\u062F \u0625\u062C\u0627\u0628\u0629 \u0627\u0642\u062A\u0631\u062D\u062A\u0647\u0627\u060C \u0639\u0628\u0631 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0645\u062A\u062A\u0628\u064E\u0651\u0639 \u0646\u0641\u0633\u0647 \u0627\u0644\u0630\u064A \u064A\u0633\u0644\u0643\u0647 \u0632\u0631 \u0627\u0644\u062A\u0623\u0643\u064A\u062F \u0641\u064A \u0627\u0644\u0628\u0648\u0627\u0628\u0629. \u0644\u0627 \u064A\u0633\u062A\u0637\u064A\u0639 \u0627\u0644\u062A\u0631\u062D\u064A\u0644 \u0623\u0648 \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0623\u0648 \u0627\u0644\u062A\u0642\u062F\u064A\u0645 \u0623\u0648 \u0625\u0631\u0633\u0627\u0644 \u0623\u064A \u0634\u064A\u0621 \u0622\u062E\u0631\u060C \u0648\u062A\u0648\u0627\u0635\u0644 \u062F\u0648\u0646\u0627 \u0641\u0631\u0636 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A \u0648\u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0643\u062A\u0627\u0628\u0629.",
  "Where the data goes": "\u0625\u0644\u0649 \u0623\u064A\u0646 \u062A\u0630\u0647\u0628 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A",
  "Tool results are sent to whichever chat provider you connect: Anthropic\u2019s cloud for Claude, OpenAI\u2019s for ChatGPT, with your account there. Turning a venture on is a per-venture decision to route that venture\u2019s data there \u2014 off by default, and off means invisible: a chat app cannot even see the venture exists.": "\u062A\u064F\u0631\u0633\u0644 \u0646\u062A\u0627\u0626\u062C \u0627\u0644\u0623\u062F\u0648\u0627\u062A \u0625\u0644\u0649 \u0645\u0632\u0648\u0651\u062F \u0627\u0644\u062F\u0631\u062F\u0634\u0629 \u0627\u0644\u0630\u064A \u062A\u0631\u0628\u0637\u0647: \u0633\u062D\u0627\u0628\u0629 Anthropic \u0644\u0640 Claude\u060C \u0648\u0633\u062D\u0627\u0628\u0629 OpenAI \u0644\u0640 ChatGPT\u060C \u0628\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u062D\u0633\u0627\u0628\u0643 \u0647\u0646\u0627\u0643. \u062A\u0641\u0639\u064A\u0644 \u0645\u0646\u0634\u0623\u0629 \u0647\u0648 \u0642\u0631\u0627\u0631 \u0645\u0633\u062A\u0642\u0644 \u0644\u0643\u0644 \u0645\u0646\u0634\u0623\u0629 \u0644\u062A\u0648\u062C\u064A\u0647 \u0628\u064A\u0627\u0646\u0627\u062A\u0647\u0627 \u0625\u0644\u0649 \u0647\u0646\u0627\u0643 \u2014 \u0648\u0647\u0648 \u0645\u062A\u0648\u0642\u0641 \u0627\u0641\u062A\u0631\u0627\u0636\u064A\u0627\u064B\u060C \u0648\u0627\u0644\u062A\u0648\u0642\u0641 \u064A\u0639\u0646\u064A \u0623\u0646\u0647\u0627 \u063A\u064A\u0631 \u0645\u0631\u0626\u064A\u0629: \u0644\u0627 \u064A\u0645\u0643\u0646 \u0644\u062A\u0637\u0628\u064A\u0642 \u0627\u0644\u062F\u0631\u062F\u0634\u0629 \u062D\u062A\u0649 \u0645\u0639\u0631\u0641\u0629 \u0648\u062C\u0648\u062F \u0627\u0644\u0645\u0646\u0634\u0623\u0629.",
  "AI chat access is disabled on this installation.": "\u0627\u0644\u0648\u0635\u0648\u0644 \u0639\u0628\u0631 \u062F\u0631\u062F\u0634\u0629 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0645\u0639\u0637\u0651\u0644 \u0641\u064A \u0647\u0630\u0627 \u0627\u0644\u062A\u062B\u0628\u064A\u062A.",
  "Reads, asks, confirms. Receipted.": "\u064A\u0642\u0631\u0623 \u0648\u064A\u0633\u0623\u0644 \u0648\u064A\u0624\u0643\u0651\u062F. \u0645\u0639 \u0625\u064A\u0635\u0627\u0644\u0627\u062A.",
  "Your call, per venture": "\u0642\u0631\u0627\u0631\u0643 \u0644\u0643\u0644 \u0645\u0646\u0634\u0623\u0629",
  "Exposure is force-disabled": "\u0627\u0644\u0625\u062A\u0627\u062D\u0629 \u0645\u0639\u0637\u0651\u0644\u0629 \u0625\u062C\u0628\u0627\u0631\u064A\u0627\u064B",
  "The kill switch is set on this installation \u2014 no venture is visible to any chat app regardless of the toggles below. Consents stay recorded and take effect again when the switch is lifted.": "\u0645\u0641\u062A\u0627\u062D \u0627\u0644\u0625\u064A\u0642\u0627\u0641 \u0645\u0636\u0628\u0648\u0637 \u0641\u064A \u0647\u0630\u0627 \u0627\u0644\u062A\u062B\u0628\u064A\u062A \u2014 \u0644\u0627 \u062A\u0638\u0647\u0631 \u0623\u064A \u0645\u0646\u0634\u0623\u0629 \u0644\u0623\u064A \u062A\u0637\u0628\u064A\u0642 \u062F\u0631\u062F\u0634\u0629 \u0628\u0635\u0631\u0641 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062A\u0628\u062F\u064A\u0644 \u0623\u062F\u0646\u0627\u0647. \u062A\u0628\u0642\u0649 \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0627\u062A \u0645\u0633\u062C\u0651\u0644\u0629 \u0648\u062A\u0639\u0648\u062F \u0625\u0644\u0649 \u0627\u0644\u0646\u0641\u0627\u0630 \u0639\u0646\u062F \u0631\u0641\u0639 \u0627\u0644\u0625\u064A\u0642\u0627\u0641.",
  "Consent recorded, but exposure is force-disabled by the kill switch.": "\u0633\u064F\u062C\u0651\u0644\u062A \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629\u060C \u0644\u0643\u0646 \u0627\u0644\u0625\u062A\u0627\u062D\u0629 \u0645\u0639\u0637\u0651\u0644\u0629 \u0625\u062C\u0628\u0627\u0631\u064A\u0627\u064B \u0628\u0648\u0627\u0633\u0637\u0629 \u0645\u0641\u062A\u0627\u062D \u0627\u0644\u0625\u064A\u0642\u0627\u0641.",
  "Turn a venture off anytime \u2014 it disappears from every connected chat app immediately. Deleting or resetting a venture also revokes its exposure; exposing it again after a reset is a new decision, never inherited.": "\u064A\u0645\u0643\u0646\u0643 \u0625\u064A\u0642\u0627\u0641 \u0645\u0646\u0634\u0623\u0629 \u0641\u064A \u0623\u064A \u0648\u0642\u062A \u2014 \u0641\u062A\u062E\u062A\u0641\u064A \u0645\u0646 \u0643\u0644 \u062A\u0637\u0628\u064A\u0642 \u062F\u0631\u062F\u0634\u0629 \u0645\u0631\u062A\u0628\u0637 \u0641\u0648\u0631\u0627\u064B. \u0643\u0645\u0627 \u064A\u0624\u062F\u064A \u062D\u0630\u0641 \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0623\u0648 \u0625\u0639\u0627\u062F\u0629 \u062A\u0639\u064A\u064A\u0646\u0647\u0627 \u0625\u0644\u0649 \u0625\u0644\u063A\u0627\u0621 \u0625\u062A\u0627\u062D\u062A\u0647\u0627\u061B \u0648\u0625\u062A\u0627\u062D\u062A\u0647\u0627 \u0645\u062C\u062F\u062F\u0627\u064B \u0628\u0639\u062F \u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u062A\u0639\u064A\u064A\u0646 \u0642\u0631\u0627\u0631 \u062C\u062F\u064A\u062F \u0644\u0627 \u064A\u064F\u0648\u0631\u062B \u0623\u0628\u062F\u0627\u064B.",
  "Donna learns these from your corrections and confirmations. Dismissing one is a recorded \u201Cno\u201D \u2014 it stays in the audit trail and stops informing her judgment.": "\u062A\u062A\u0639\u0644\u0645 \u062F\u0648\u0646\u0627 \u0647\u0630\u0647 \u0627\u0644\u062D\u0642\u0627\u0626\u0642 \u0645\u0646 \u062A\u0635\u062D\u064A\u062D\u0627\u062A\u0643 \u0648\u062A\u0623\u0643\u064A\u062F\u0627\u062A\u0643. \u0627\u0633\u062A\u0628\u0639\u0627\u062F \u0625\u062D\u062F\u0627\u0647\u0627 \u0647\u0648 \xAB\u0644\u0627\xBB \u0645\u0633\u062C\u0651\u0644\u0629 \u2014 \u062A\u0628\u0642\u0649 \u0641\u064A \u0645\u0633\u0627\u0631 \u0627\u0644\u062A\u062F\u0642\u064A\u0642 \u0648\u062A\u062A\u0648\u0642\u0641 \u0639\u0646 \u0627\u0644\u062A\u0623\u062B\u064A\u0631 \u0641\u064A \u062D\u0643\u0645\u0647\u0627.",
  "The database is the book \u2014 Donna packages a verified snapshot (database + every source document) on schedule and keeps a rolling window.": "\u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0647\u064A \u0627\u0644\u062F\u0641\u0627\u062A\u0631 \u2014 \u062A\u062D\u0632\u0645 \u062F\u0648\u0646\u0627 \u0644\u0642\u0637\u0629 \u0645\u062A\u062D\u0642\u0651\u064E\u0642\u0627\u064B \u0645\u0646\u0647\u0627 (\u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0643\u0644 \u0645\u0633\u062A\u0646\u062F \u0645\u0635\u062F\u0631) \u0648\u0641\u0642 \u0627\u0644\u062C\u062F\u0648\u0644 \u0648\u062A\u062D\u062A\u0641\u0638 \u0628\u0646\u0627\u0641\u0630\u0629 \u0645\u062A\u062C\u062F\u062F\u0629.",
  "Posting to the ledger is deterministic machinery and is never delegated to a model.": "\u0627\u0644\u062A\u0631\u062D\u064A\u0644 \u0625\u0644\u0649 \u062F\u0641\u062A\u0631 \u0627\u0644\u0623\u0633\u062A\u0627\u0630 \u0639\u0645\u0644\u064A\u0629 \u062D\u062A\u0645\u064A\u0629 \u0648\u0644\u0627 \u064A\u064F\u0641\u0648\u0651\u064E\u0636 \u0623\u0628\u062F\u0627\u064B \u0625\u0644\u0649 \u0646\u0645\u0648\u0630\u062C.",
  "Inspect and map a spreadsheet before writing any transaction.": "\u0627\u0641\u062D\u0635 \u062C\u062F\u0648\u0644 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0637\u0627\u0628\u0642 \u0623\u0639\u0645\u062F\u062A\u0647 \u0642\u0628\u0644 \u0643\u062A\u0627\u0628\u0629 \u0623\u064A \u0645\u0639\u0627\u0645\u0644\u0629.",
  "Donna never assumes that an unknown CSV is a bank statement.": "\u0644\u0627 \u062A\u0641\u062A\u0631\u0636 \u062F\u0648\u0646\u0627 \u0623\u0628\u062F\u0627\u064B \u0623\u0646 \u0645\u0644\u0641 CSV \u063A\u064A\u0631 \u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0643\u0634\u0641 \u062D\u0633\u0627\u0628 \u0628\u0646\u0643\u064A.",
  "Nothing has been written. Resolve every listed row or workbook issue first.": "\u0644\u0645 \u062A\u062A\u0645 \u0643\u062A\u0627\u0628\u0629 \u0623\u064A \u0634\u064A\u0621. \u0639\u0627\u0644\u062C \u0623\u0648\u0644\u0627\u064B \u0643\u0644 \u0645\u0634\u0643\u0644\u0629 \u0645\u062F\u0631\u062C\u0629 \u0641\u064A \u0635\u0641 \u0623\u0648 \u0645\u0635\u0646\u0641.",
  "This is a read-only preview. No accounting data has been written.": "\u0647\u0630\u0647 \u0645\u0639\u0627\u064A\u0646\u0629 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0641\u0642\u0637. \u0644\u0645 \u062A\u062A\u0645 \u0643\u062A\u0627\u0628\u0629 \u0623\u064A \u0628\u064A\u0627\u0646\u0627\u062A \u0645\u062D\u0627\u0633\u0628\u064A\u0629.",
  "Drop anything that identifies the business \u2014 a bank statement works best; a registry extract, tax notice or invoice also works.": "\u0623\u0641\u0644\u062A \u0623\u064A \u0645\u0633\u062A\u0646\u062F \u064A\u0639\u0631\u0651\u0641 \u0627\u0644\u0646\u0634\u0627\u0637 \u2014 \u0643\u0634\u0641 \u0627\u0644\u062D\u0633\u0627\u0628 \u0627\u0644\u0628\u0646\u0643\u064A \u0647\u0648 \u0627\u0644\u0623\u0641\u0636\u0644\u061B \u0648\u064A\u0645\u0643\u0646 \u0623\u064A\u0636\u0627\u064B \u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0645\u0633\u062A\u062E\u0631\u062C \u0627\u0644\u0633\u062C\u0644 \u0623\u0648 \u0625\u0634\u0639\u0627\u0631 \u0636\u0631\u064A\u0628\u064A \u0623\u0648 \u0641\u0627\u062A\u0648\u0631\u0629.",
  "Nothing sends or posts without your approval. You approve any standing authority separately.": "\u0644\u0627 \u064A\u064F\u0631\u0633\u0644 \u0623\u0648 \u064A\u064F\u0631\u062D\u0651\u0644 \u0623\u064A \u0634\u064A\u0621 \u0645\u0646 \u062F\u0648\u0646 \u0645\u0648\u0627\u0641\u0642\u062A\u0643. \u062A\u0648\u0627\u0641\u0642 \u0639\u0644\u0649 \u0623\u064A \u0635\u0644\u0627\u062D\u064A\u0629 \u062F\u0627\u0626\u0645\u0629 \u0628\u0635\u0648\u0631\u0629 \u0645\u0646\u0641\u0635\u0644\u0629.",
  "Donna closes your books each month, shows what she did, and asks when your facts or approval are needed. Start your plan to upload documents and let Donna keep your books closed.": "\u062A\u064F\u0642\u0641\u0644 \u062F\u0648\u0646\u0627 \u062F\u0641\u0627\u062A\u0631\u0643 \u0643\u0644 \u0634\u0647\u0631\u060C \u0648\u062A\u0639\u0631\u0636 \u0645\u0627 \u0641\u0639\u0644\u062A\u0647\u060C \u0648\u062A\u0633\u0623\u0644 \u0639\u0646\u062F\u0645\u0627 \u062A\u062D\u062A\u0627\u062C \u0625\u0644\u0649 \u062D\u0642\u0627\u0626\u0642\u0643 \u0623\u0648 \u0645\u0648\u0627\u0641\u0642\u062A\u0643. \u0627\u0628\u062F\u0623 \u062E\u0637\u062A\u0643 \u0644\u0631\u0641\u0639 \u0627\u0644\u0645\u0633\u062A\u0646\u062F\u0627\u062A \u0648\u062F\u0639 \u062F\u0648\u0646\u0627 \u062A\u062D\u0627\u0641\u0638 \u0639\u0644\u0649 \u0625\u0642\u0641\u0627\u0644 \u062F\u0641\u0627\u062A\u0631\u0643."
});
