  "operator.providerFailure.attempts": "\u0639\u0645\u0644\u064A\u0627\u062A \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0641\u0627\u0634\u0644\u0629: {count}",
